import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"23、【剝】 坤下艮上","description":"橫渠易說 - 23、【剝】 坤下艮上","frontmatter":{"title":"23、【剝】 坤下艮上","description":"橫渠易說 - 23、【剝】 坤下艮上"},"headers":[],"relativePath":"classics/hengqu/025.md","filePath":"classics/hengqu/025.md"}'),l={name:"classics/hengqu/025.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_23、【剝】-坤下艮上" tabindex="-1">23、【剝】 坤下艮上 <a class="header-anchor" href="#_23、【剝】-坤下艮上" aria-label="Permalink to “23、【剝】 坤下艮上”">​</a></h1><h3 id="彖曰-剝-剝也-柔變剛也。-不利有攸往-小人長也。順而止之-觀象也。君子尚消息盈虛-天行也。" tabindex="-1">彖曰，剝，剝也，柔變剛也。“不利有攸往”，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。 <a class="header-anchor" href="#彖曰-剝-剝也-柔變剛也。-不利有攸往-小人長也。順而止之-觀象也。君子尚消息盈虛-天行也。" aria-label="Permalink to “彖曰，剝，剝也，柔變剛也。“不利有攸往”，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。”">​</a></h3><h3 id="象曰-山附於地-剝-上以厚下安宅。" tabindex="-1">象曰：山附於地，剝，上以厚下安宅。 <a class="header-anchor" href="#象曰-山附於地-剝-上以厚下安宅。" aria-label="Permalink to “象曰：山附於地，剝，上以厚下安宅。”">​</a></h3><p>處剝之時，順上以觀天理之消息盈虛。</p><h3 id="初六-剝床以足-蔑貞兇。-象曰-剝床以足-以滅下也。" tabindex="-1">初六，剝床以足，蔑貞兇。 象曰：“剝床以足”，以滅下也。 <a class="header-anchor" href="#初六-剝床以足-蔑貞兇。-象曰-剝床以足-以滅下也。" aria-label="Permalink to “初六，剝床以足，蔑貞兇。 象曰：“剝床以足”，以滅下也。”">​</a></h3><h3 id="六二-剝床以辨-蔑貞兇。-象曰-剝床以辨-未有與也。" tabindex="-1">六二，剝床以辨，蔑貞兇。 象曰：“剝床以辨”，未有與也。 <a class="header-anchor" href="#六二-剝床以辨-蔑貞兇。-象曰-剝床以辨-未有與也。" aria-label="Permalink to “六二，剝床以辨，蔑貞兇。 象曰：“剝床以辨”，未有與也。”">​</a></h3><p>三雖陰類，然志應在上，二不能進剝陽爻，徒用口舌間說，力未能勝，故象曰“未有與也”。然志在滅陽，故亦云“蔑貞兇”。</p><h3 id="六三-剝之-無咎。-象曰-剝之無咎-失上下也。" tabindex="-1">六三，剝之，無咎。 象曰：“剝之無咎”，失上下也。 <a class="header-anchor" href="#六三-剝之-無咎。-象曰-剝之無咎-失上下也。" aria-label="Permalink to “六三，剝之，無咎。 象曰：“剝之無咎”，失上下也。”">​</a></h3><p>獨應於陽，故反為眾陰所剝，然無所咎。</p><h3 id="六四-剝床以膚-兇。-象曰-剝床以膚-切近災也。" tabindex="-1">六四，剝床以膚，兇。 象曰：“剝床以膚”，切近災也。 <a class="header-anchor" href="#六四-剝床以膚-兇。-象曰-剝床以膚-切近災也。" aria-label="Permalink to “六四，剝床以膚，兇。 象曰：“剝床以膚”，切近災也。”">​</a></h3><p>迫近君位，猶自下剝床，至床之膚，將及於人也。不言“蔑貞”，剝道成矣。一雲：五於陰陽之際，義必上比，故以喻膚。</p><h3 id="六五-貫魚以宮人寵-無不利。-象曰-以宮人寵-終無尤也。" tabindex="-1">六五，貫魚以宮人寵，無不利。 象曰：“以宮人寵”，終無尤也。 <a class="header-anchor" href="#六五-貫魚以宮人寵-無不利。-象曰-以宮人寵-終無尤也。" aria-label="Permalink to “六五，貫魚以宮人寵，無不利。 象曰：“以宮人寵”，終無尤也。”">​</a></h3><p>六五為上九之膚，能下寵眾陰，則陽獲安而無不利矣。異於六三者，以其居尊制裁，為卦之主，故不雲“剝之”也。終無尤怨者，以小人之心不過圖寵利而已，不以宮人見畜為恥也。陰陽之際，近必相比，六五能上附於陽，反制群陰不使進逼，方得處剝之善，下無剝之之憂，上得陽功之庇，故曰“無不利”。</p><h3 id="上九-碩果不食-君子得輿-小人剝廬。-象曰-君子得輿-民所載也。-小人剝廬-終不可用也。" tabindex="-1">上九，碩果不食，君子得輿，小人剝廬。 象曰：“君子得輿”，民所載也。“小人剝廬”，終不可用也。 <a class="header-anchor" href="#上九-碩果不食-君子得輿-小人剝廬。-象曰-君子得輿-民所載也。-小人剝廬-終不可用也。" aria-label="Permalink to “上九，碩果不食，君子得輿，小人剝廬。 象曰：“君子得輿”，民所載也。“小人剝廬”，終不可用也。”">​</a></h3><p>處剝之世，有美實而不見採，然其德備，猶為民所載。小人處下則剝床，處上則反傷於下，是終不可用之也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
